package hgc.flowsyncapi.controller;import hgc.flowsyncapi.common.ApiResponse;import hgc.flowsyncapi.dto.LoginRequest;import hgc.flowsyncapi.service.AuthService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/auth")public class AuthController{private final AuthService s;public AuthController(AuthService x){s=x;}@PostMapping("/login")public ApiResponse<Map<String,Object>>login(@RequestBody LoginRequest r){return ApiResponse.success("登录成功",s.login(r));}}